import fs from "node:fs";
import path from "node:path";
import { LOCALE_COOKIE, localeNames, locales, type Locale } from "@/i18n/config";

/**
 * Pages are generated by scripts/clone/build.py into site/<locale>/<key>.html.
 * site/manifest.json maps every page key to its URL in each language.
 */
const SITE_DIR = path.join(process.cwd(), "site");

type Manifest = Record<string, Record<Locale, string>>;

let manifestCache: Manifest | null = null;
const headerCache: Partial<Record<Locale, string>> = {};

export function manifest(): Manifest {
  manifestCache ??= JSON.parse(fs.readFileSync(path.join(SITE_DIR, "manifest.json"), "utf8")) as Manifest;
  return manifestCache;
}

/** URL path (e.g. "/es/calculadora/") → page key, per language. */
export function findPage(locale: Locale, urlPath: string): string | undefined {
  const normalized = urlPath.endsWith("/") ? urlPath : `${urlPath}/`;
  const m = manifest();
  return Object.keys(m).find((k) => m[k][locale] === normalized);
}

export function allPaths(): { locale: Locale; slug: string[] }[] {
  const m = manifest();
  return locales.flatMap((locale) =>
    Object.values(m).map((alts) => ({
      locale,
      slug: alts[locale].split("/").filter(Boolean).slice(1),
    })),
  );
}

function header(locale: Locale): string {
  headerCache[locale] ??= fs.readFileSync(path.join(SITE_DIR, locale, "_header.html"), "utf8");
  return headerCache[locale]!;
}

const remember = (l: Locale) =>
  `document.cookie='${LOCALE_COOKIE}=${l};path=/;max-age=31536000;samesite=lax'`;

const GLOBE =
  '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg>';

function switcher(locale: Locale, alts: Record<Locale, string>, mobile: boolean): string {
  const label = locale === "es" ? "Idioma" : "Language";
  if (!mobile) {
    // Desktop: one compact button that goes to the other language.
    const other = locales.find((l) => l !== locale)!;
    return `<a class="pd-lang-toggle" href="${alts[other]}" hreflang="${other}" lang="${other}" title="${localeNames[other]}" aria-label="${label}: ${localeNames[other]}" onclick="${remember(other)}">${GLOBE}<span>${other.toUpperCase()}</span></a>`;
  }
  const links = locales
    .map((l) => {
      const current = l === locale ? ' aria-current="true"' : "";
      return `<a class="pd-lang-opt" href="${alts[l]}" hreflang="${l}" lang="${l}" onclick="${remember(l)}"${current}>${localeNames[l]}</a>`;
    })
    .join("");
  return `<nav class="pd-lang pd-lang-mobile" aria-label="${label}">${GLOBE}${links}</nav>`;
}

export function renderPage(locale: Locale, key: string): string {
  const alts = manifest()[key];
  const siteUrl = (process.env.NEXT_PUBLIC_SITE_URL ?? "").replace(/\/$/, "");
  return fs
    .readFileSync(path.join(SITE_DIR, locale, `${key}.html`), "utf8")
    .replace("<!--@header-->", () => header(locale))
    .replace("<!--@lang-->", () => switcher(locale, alts, false))
    .replace("<!--@lang-mobile-->", () => switcher(locale, alts, true))
    .replaceAll("__SITE_URL__", siteUrl);
}
